// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e24);
        vm.deal(address(this), amount);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);
        c.withdrawAll();
        // Reference C sends its whole balance to the owner on withdrawAll;
        // the mutant sends 0, so the balance stays positive.
        assertTrue(address(c).balance == 0);
    }
}
